def maxSubarray(nums):
    MAXV = 500
    cnt = [0] * (MAXV + 1)      # counts of each value inside the current window

    def conflicts(v):
        # The window currently does NOT contain the new element v.
        # Case 1: v equals the sum of two other elements at different indices
        for u in range(1, v // 2 + 1):
            w = v - u
            if u == w:
                if cnt[u] >= 2:
                    return True
            elif cnt[u] >= 1 and cnt[w] >= 1:
                return True
        # Case 2: v is an addend: some u in the window with u + v also in the window
        for u in range(1, MAXV - v + 1):
            if cnt[u] >= 1 and cnt[u + v] >= 1:
                return True
        return False

    left = 0
    best = 0
    for right, v in enumerate(nums):
        # Shrink from the left until adding v creates no bad triple
        while left < right and conflicts(v):
            cnt[nums[left]] -= 1
            left += 1
        cnt[v] += 1
        best = max(best, right - left + 1)
    return best
